// OTOMATİK ÜRETİLDİ — elle düzenlemeyin. Kaynak: shared/plan-template.ts (fitPlanToPage). Yenile: npm run gen:fit
export const FIT_PLAN_SOURCE = "\"use strict\";\nfunction fitPlanToPage(doc, minScale, recipeMinScale = 0.7) {\n    const sheet = doc.getElementById('sheet');\n    if (!sheet)\n        return { scale: 1, fits: true, pages: 1, recipesFit: true };\n    const overflows = (el) => el.scrollHeight > el.clientHeight + 1;\n    const shrink = (el, min) => {\n        let v = 1;\n        el.style.setProperty('--s', '1');\n        while (overflows(el) && v > min) {\n            v = Math.round((v - 0.02) * 100) / 100;\n            el.style.setProperty('--s', String(v));\n        }\n        return { v, ok: !overflows(el) };\n    };\n    const first = shrink(sheet, minScale);\n    let pages = 1;\n    let recipesFit = true;\n    const pool = doc.getElementById('recipe-pool');\n    const tpl = doc.getElementById('recipe-sheet-tpl');\n    if (pool && tpl) {\n        for (const old of Array.from(doc.querySelectorAll('.rsheet'))) {\n            for (const b of Array.from(old.querySelectorAll('.recipe')))\n                pool.appendChild(b);\n            old.remove();\n        }\n        const blocks = Array.from(pool.querySelectorAll('.recipe'));\n        let cur = null;\n        const newSheet = () => {\n            const s = doc.importNode(tpl.content.firstElementChild, true);\n            pool.parentNode.insertBefore(s, pool);\n            pages += 1;\n            return s;\n        };\n        for (const block of blocks) {\n            if (!cur)\n                cur = newSheet();\n            let list = cur.querySelector('.rlist');\n            list.appendChild(block);\n            if (!overflows(cur))\n                continue;\n            if (list.children.length > 1) {\n                cur = newSheet();\n                list = cur.querySelector('.rlist');\n                list.appendChild(block);\n            }\n            if (overflows(cur)) {\n                if (!shrink(cur, recipeMinScale).ok)\n                    recipesFit = false;\n                cur = null;\n            }\n        }\n    }\n    return { scale: first.v, fits: first.ok, pages, recipesFit };\n}";
